from decimal import Decimal, ROUND_HALF_EVEN


def _to_cents(s):
    """Parse a decimal money string into an integer number of cents (half-even on sub-cent)."""
    q = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
    return int((q * 100).to_integral_value(rounding=ROUND_HALF_EVEN))


def _cents_to_str(c):
    """Format integer cents as a normalized 'X.XX' string."""
    sign = "-" if c < 0 else ""
    c = abs(c)
    return f"{sign}{c // 100}.{c % 100:02d}"


def add(a, b):
    return _cents_to_str(_to_cents(a) + _to_cents(b))


def split(total, n):
    if n <= 0:
        raise ValueError("n must be a positive integer")
    total_cents = _to_cents(total)
    base, rem = divmod(total_cents, n)  # rem is in [0, n) since n > 0
    # Give the first `rem` parts one extra cent so the parts sum exactly to total.
    parts = [base + 1 if i < rem else base for i in range(n)]
    return [_cents_to_str(c) for c in parts]


def round_money(value):
    q = Decimal(value).quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
    return _cents_to_str(int((q * 100).to_integral_value(rounding=ROUND_HALF_EVEN)))
